mapper.select:
select * from (
    select

    from t_glue_decompose_plan tgdp
    where tgdp.del_flag = '0'
    and tgdp.plan_date = #{planDate}
    and tgdp.mix_area = #{mixArea}
    and INSTR(tgdp.glue, #{glue}) > 0
    and tgdp.machine_code = #{machineCode}
) t

    order by glue


    order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, plan_date, mix_area, glue FROM dual
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_glue_decompose_plan m inner join temp_table t on m.plan_date = t.plan_date and m.mix_area = t.mix_area and m.glue = t.glue and m.del_flag ='0'

mapper.insert:
insert into t_glue_decompose_plan
(id,collect_batch_no,batch_no,plan_date,mix_area,glue,plan_qty,stock_qty,safe_stock_qty,produce_qty,machine_code,data_source,remark,del_flag,create_by,create_time,update_by,update_time
)
select NULL id, x.*
from (

    select
    #{glueDecomposePlan.collectBatchNo,jdbcType= VARCHAR} collect_batch_no,
    #{glueDecomposePlan.batchNo,jdbcType= VARCHAR} batch_no, #{glueDecomposePlan.planDate,jdbcType=DATE}
    plan_date,
    #{glueDecomposePlan.mixArea,jdbcType= VARCHAR} mix_area, #{glueDecomposePlan.glue,jdbcType= VARCHAR} glue,
    #{glueDecomposePlan.planQty,jdbcType=DOUBLE} plan_qty, #{glueDecomposePlan.stockQty,jdbcType=DOUBLE}
    stock_qty, #{glueDecomposePlan.safeStockQty,jdbcType=DOUBLE} safe_stock_qty,
    #{glueDecomposePlan.produceQty,jdbcType=DOUBLE} produce_qty,
    #{glueDecomposePlan.machineCode,jdbcType= VARCHAR} machine_code,
    #{glueDecomposePlan.dataSource,jdbcType= VARCHAR} data_source, #{glueDecomposePlan.remark,jdbcType= VARCHAR}
    remark, #{glueDecomposePlan.delFlag,jdbcType= VARCHAR} del_flag,
    #{glueDecomposePlan.createBy,jdbcType= VARCHAR} create_by, #{glueDecomposePlan.createTime,jdbcType=DATE}
    create_time, #{glueDecomposePlan.updateBy,jdbcType= VARCHAR} update_by,
    #{glueDecomposePlan.updateTime,jdbcType=DATE} update_time from dual

) x

mapper.update:
with temp_data as(
select #{item.id, jdbcType=DOUBLE} id, #{item.planQty, jdbcType=DOUBLE} plan_qty,#{item.safeStockQty, jdbcType=DOUBLE} safe_stock_qty, #{item.stockQty, jdbcType=DOUBLE} stock_qty, #{item.produceQty, jdbcType=DOUBLE} produce_qty, #{item.machineCode,jdbcType=VARCHAR } machine_code, #{item.remark,jdbcType=VARCHAR } remark, #{item.updateBy,jdbcType=VARCHAR } update_by, #{item.updateTime, jdbcType=DATE} update_time
) update t_glue_decompose_plan a join temp_data b on a.id = b.id set a.plan_qty = b.plan_qty,a.stock_qty = b.stock_qty,a.safe_stock_qty = b.safe_stock_qty, a.produce_qty = b.produce_qty, a.machine_code = b.machine_code, a.remark = b.remark, a.update_by = b.update_by, a.update_time = now() where a.DEL_FLAG = '0'

